import numpy as np

def feature(item, bins, capacity):
    """Remaining room of each candidate bin divided by capacity (emptiest bin highest; new bin = 1)."""
    return bins.astype(float) / float(capacity)

import numpy as np

def feature(item, bins, capacity):
    """Squared snugness (item/room)^2 minus 0.5, clipped to [-0.5, 0.5]."""
    ratio = item / np.maximum(bins.astype(float), 1.0)
    return np.clip(ratio * ratio - 0.5, -0.5, 0.5)

